7536|int nghttp2_session_add_settings(nghttp2_session *session, uint8_t flags,
7537|                                 const nghttp2_settings_entry *iv, size_t niv) {
7538|  nghttp2_outbound_item *item;
7539|  nghttp2_frame *frame;
7540|  nghttp2_settings_entry *iv_copy;
7541|  size_t i;
7542|  int rv;
7543|  nghttp2_mem *mem;
7544|  nghttp2_inflight_settings *inflight_settings = NULL;
7545|  uint8_t no_rfc7540_pri = session->pending_no_rfc7540_priorities;
7546|
7547|  mem = &session->mem;
7548|
7549|  if (flags & NGHTTP2_FLAG_ACK) {
7550|    if (niv != 0) {
7551|      return NGHTTP2_ERR_INVALID_ARGUMENT;
7552|    }
7553|
7554|    if (session->obq_flood_counter_ >= session->max_outbound_ack) {
7555|      return NGHTTP2_ERR_FLOODED;
7556|    }
7557|  }
7558|
7559|  if (!nghttp2_iv_check(iv, niv)) {
7560|    return NGHTTP2_ERR_INVALID_ARGUMENT;
7561|  }
7562|
7563|  for (i = 0; i < niv; ++i) {
7564|    if (iv[i].settings_id != NGHTTP2_SETTINGS_NO_RFC7540_PRIORITIES) {
7565|      continue;
7566|    }
7567|
7568|    if (no_rfc7540_pri == UINT8_MAX) {
7569|      no_rfc7540_pri = (uint8_t)iv[i].value;
7570|      continue;
7571|    }
7572|
7573|    if (iv[i].value != (uint32_t)no_rfc7540_pri) {
7574|      return NGHTTP2_ERR_INVALID_ARGUMENT;
7575|    }
7576|  }
7577|
7578|  item = nghttp2_mem_malloc(mem, sizeof(nghttp2_outbound_item));
7579|  if (item == NULL) {
7580|    return NGHTTP2_ERR_NOMEM;
7581|  }
7582|
7583|  if (niv > 0) {
7584|    iv_copy = nghttp2_frame_iv_copy(iv, niv, mem);
7585|    if (iv_copy == NULL) {
7586|      nghttp2_mem_free(mem, item);
7587|      return NGHTTP2_ERR_NOMEM;
7588|    }
7589|  } else {
7590|    iv_copy = NULL;
7591|  }
7592|
7593|  if ((flags & NGHTTP2_FLAG_ACK) == 0) {
7594|    rv = inflight_settings_new(&inflight_settings, iv, niv, mem);
7595|    if (rv != 0) {
7596|      assert(nghttp2_is_fatal(rv));
7597|      nghttp2_mem_free(mem, iv_copy);
7598|      nghttp2_mem_free(mem, item);
7599|      return rv;
7600|    }
7601|  }
7602|
7603|  nghttp2_outbound_item_init(item);
7604|
7605|  frame = &item->frame;
7606|
7607|  nghttp2_frame_settings_init(&frame->settings, flags, iv_copy, niv);
7608|  rv = nghttp2_session_add_item(session, item);
7609|  if (rv != 0) {
7610|    /* The only expected error is fatal one */
7611|    assert(nghttp2_is_fatal(rv));
7612|
7613|    inflight_settings_del(inflight_settings, mem);
7614|
7615|    nghttp2_frame_settings_free(&frame->settings, mem);
7616|    nghttp2_mem_free(mem, item);
7617|
7618|    return rv;
7619|  }
7620|
7621|  if (flags & NGHTTP2_FLAG_ACK) {
7622|    ++session->obq_flood_counter_;
7623|  } else {
7624|    session_append_inflight_settings(session, inflight_settings);
7625|  }
7626|
7627|  /* Extract NGHTTP2_SETTINGS_MAX_CONCURRENT_STREAMS and ENABLE_PUSH
7628|     here.  We use it to refuse the incoming stream and PUSH_PROMISE
7629|     with RST_STREAM. */
7630|
7631|  for (i = niv; i > 0; --i) {
7632|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_MAX_CONCURRENT_STREAMS) {
7633|      session->pending_local_max_concurrent_stream = iv[i - 1].value;
7634|      break;
7635|    }
7636|  }
7637|
7638|  for (i = niv; i > 0; --i) {
7639|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_ENABLE_PUSH) {
7640|      session->pending_enable_push = (uint8_t)iv[i - 1].value;
7641|      break;
7642|    }
7643|  }
7644|
7645|  for (i = niv; i > 0; --i) {
7646|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_ENABLE_CONNECT_PROTOCOL) {
7647|      session->pending_enable_connect_protocol = (uint8_t)iv[i - 1].value;
7648|      break;
7649|    }
7650|  }
7651|
7652|  if (no_rfc7540_pri == UINT8_MAX) {
7653|    session->pending_no_rfc7540_priorities = 0;
7654|  } else {
7655|    session->pending_no_rfc7540_priorities = no_rfc7540_pri;
7656|  }
7657|
7658|  return 0;
7659|}

4948|static int session_process_settings_frame(nghttp2_session *session) {
4949|  nghttp2_inbound_frame *iframe = &session->iframe;
4950|  nghttp2_frame *frame = &iframe->frame;
4951|  size_t i;
4952|  nghttp2_settings_entry min_header_size_entry;
4953|
4954|  if (iframe->max_niv) {
4955|    min_header_size_entry = iframe->iv[iframe->max_niv - 1];
4956|
4957|    if (min_header_size_entry.value < UINT32_MAX) {
4958|      /* If we have less value, then we must have
4959|         SETTINGS_HEADER_TABLE_SIZE in i < iframe->niv */
4960|      for (i = 0; i < iframe->niv; ++i) {
4961|        if (iframe->iv[i].settings_id == NGHTTP2_SETTINGS_HEADER_TABLE_SIZE) {
4962|          break;
4963|        }
4964|      }
4965|
4966|      assert(i < iframe->niv);
4967|
4968|      if (min_header_size_entry.value != iframe->iv[i].value) {
4969|        iframe->iv[iframe->niv++] = iframe->iv[i];
4970|        iframe->iv[i] = min_header_size_entry;
4971|      }
4972|    }
4973|  }
4974|
4975|  nghttp2_frame_unpack_settings_payload(&frame->settings, iframe->iv,
4976|                                        iframe->niv);
4977|
4978|  iframe->iv = NULL;
4979|  iframe->niv = 0;
4980|  iframe->max_niv = 0;
4981|
4982|  return nghttp2_session_on_settings_received(session, frame, 0 /* ACK */);
4983|}

3237|static ssize_t nghttp2_session_mem_send_internal(nghttp2_session *session,
3238|                                                 const uint8_t **data_ptr,
3239|                                                 int fast_cb) {
3240|  int rv;
3241|  nghttp2_active_outbound_item *aob;
3242|  nghttp2_bufs *framebufs;
3243|  nghttp2_mem *mem;
3244|
3245|  mem = &session->mem;
3246|  aob = &session->aob;
3247|  framebufs = &aob->framebufs;
3248|
3249|  /* We may have idle streams more than we expect (e.g.,
3250|     nghttp2_session_change_stream_priority() or
3251|     nghttp2_session_create_idle_stream()).  Adjust them here. */
3252|  rv = nghttp2_session_adjust_idle_stream(session);
3253|  if (nghttp2_is_fatal(rv)) {
3254|    return rv;
3255|  }
3256|
3257|  for (;;) {
3258|    switch (aob->state) {
3259|    case NGHTTP2_OB_POP_ITEM: {
3260|      nghttp2_outbound_item *item;
3261|
3262|      item = nghttp2_session_pop_next_ob_item(session);
3263|      if (item == NULL) {
3264|        return 0;
3265|      }
3266|
3267|      rv = session_prep_frame(session, item);
3268|      if (rv == NGHTTP2_ERR_PAUSE) {
3269|        return 0;
3270|      }
3271|      if (rv == NGHTTP2_ERR_DEFERRED) {
3272|        DEBUGF("send: frame transmission deferred\n");
3273|        break;
3274|      }
3275|      if (rv < 0) {
3276|        int32_t opened_stream_id = 0;
3277|        uint32_t error_code = NGHTTP2_INTERNAL_ERROR;
3278|
3279|        DEBUGF("send: frame preparation failed with %s\n",
3280|               nghttp2_strerror(rv));
3281|        /* TODO If the error comes from compressor, the connection
3282|           must be closed. */
3283|        if (item->frame.hd.type != NGHTTP2_DATA &&
3284|            session->callbacks.on_frame_not_send_callback && is_non_fatal(rv)) {
3285|          nghttp2_frame *frame = &item->frame;
3286|          /* The library is responsible for the transmission of
3287|             WINDOW_UPDATE frame, so we don't call error callback for
3288|             it. */
3289|          if (frame->hd.type != NGHTTP2_WINDOW_UPDATE &&
3290|              session->callbacks.on_frame_not_send_callback(
3291|                  session, frame, rv, session->user_data) != 0) {
3292|
3293|            nghttp2_outbound_item_free(item, mem);
3294|            nghttp2_mem_free(mem, item);
3295|
3296|            return NGHTTP2_ERR_CALLBACK_FAILURE;
3297|          }
3298|        }
3299|        /* We have to close stream opened by failed request HEADERS
3300|           or PUSH_PROMISE. */
3301|        switch (item->frame.hd.type) {
3302|        case NGHTTP2_HEADERS:
3303|          if (item->frame.headers.cat == NGHTTP2_HCAT_REQUEST) {
3304|            opened_stream_id = item->frame.hd.stream_id;
3305|            if (item->aux_data.headers.canceled) {
3306|              error_code = item->aux_data.headers.error_code;
3307|            } else {
3308|              /* Set error_code to REFUSED_STREAM so that application
3309|                 can send request again. */
3310|              error_code = NGHTTP2_REFUSED_STREAM;
3311|            }
3312|          }
3313|          break;
3314|        case NGHTTP2_PUSH_PROMISE:
3315|          opened_stream_id = item->frame.push_promise.promised_stream_id;
3316|          break;
3317|        }
3318|        if (opened_stream_id) {
3319|          /* careful not to override rv */
3320|          int rv2;
3321|          rv2 = nghttp2_session_close_stream(session, opened_stream_id,
3322|                                             error_code);
3323|
3324|          if (nghttp2_is_fatal(rv2)) {
3325|            return rv2;
3326|          }
3327|        }
3328|
3329|        nghttp2_outbound_item_free(item, mem);
3330|        nghttp2_mem_free(mem, item);
3331|        active_outbound_item_reset(aob, mem);
3332|
3333|        if (rv == NGHTTP2_ERR_HEADER_COMP) {
3334|          /* If header compression error occurred, should terminiate
3335|             connection. */
3336|          rv = nghttp2_session_terminate_session(session,
3337|                                                 NGHTTP2_INTERNAL_ERROR);
3338|        }
3339|        if (nghttp2_is_fatal(rv)) {
3340|          return rv;
3341|        }
3342|        break;
3343|      }
3344|
3345|      aob->item = item;
3346|
3347|      nghttp2_bufs_rewind(framebufs);
3348|
3349|      if (item->frame.hd.type != NGHTTP2_DATA) {
3350|        nghttp2_frame *frame;
3351|
3352|        frame = &item->frame;
3353|
3354|        DEBUGF("send: next frame: payloadlen=%zu, type=%u, flags=0x%02x, "
3355|               "stream_id=%d\n",
3356|               frame->hd.length, frame->hd.type, frame->hd.flags,
3357|               frame->hd.stream_id);
3358|
3359|        rv = session_call_before_frame_send(session, frame);
3360|        if (nghttp2_is_fatal(rv)) {
3361|          return rv;
3362|        }
3363|
3364|        if (rv == NGHTTP2_ERR_CANCEL) {
3365|          int32_t opened_stream_id = 0;
3366|          uint32_t error_code = NGHTTP2_INTERNAL_ERROR;
3367|
3368|          if (session->callbacks.on_frame_not_send_callback) {
3369|            if (session->callbacks.on_frame_not_send_callback(
3370|                    session, frame, rv, session->user_data) != 0) {
3371|              return NGHTTP2_ERR_CALLBACK_FAILURE;
3372|            }
3373|          }
3374|
3375|          /* We have to close stream opened by canceled request
3376|             HEADERS or PUSH_PROMISE. */
3377|          switch (item->frame.hd.type) {
3378|          case NGHTTP2_HEADERS:
3379|            if (item->frame.headers.cat == NGHTTP2_HCAT_REQUEST) {
3380|              opened_stream_id = item->frame.hd.stream_id;
3381|              /* We don't have to check
3382|                 item->aux_data.headers.canceled since it has already
3383|                 been checked. */
3384|              /* Set error_code to REFUSED_STREAM so that application
3385|                 can send request again. */
3386|              error_code = NGHTTP2_REFUSED_STREAM;
3387|            }
3388|            break;
3389|          case NGHTTP2_PUSH_PROMISE:
3390|            opened_stream_id = item->frame.push_promise.promised_stream_id;
3391|            break;
3392|          }
3393|          if (opened_stream_id) {
3394|            /* careful not to override rv */
3395|            int rv2;
3396|            rv2 = nghttp2_session_close_stream(session, opened_stream_id,
3397|                                               error_code);
3398|
3399|            if (nghttp2_is_fatal(rv2)) {
3400|              return rv2;
3401|            }
3402|          }
3403|
3404|          active_outbound_item_reset(aob, mem);
3405|
3406|          break;
3407|        }
3408|      } else {
3409|        DEBUGF("send: next frame: DATA\n");
3410|
3411|        if (item->aux_data.data.no_copy) {
3412|          aob->state = NGHTTP2_OB_SEND_NO_COPY;
3413|          break;
3414|        }
3415|      }
3416|
3417|      DEBUGF("send: start transmitting frame type=%u, length=%zd\n",
3418|             framebufs->cur->buf.pos[3],
3419|             framebufs->cur->buf.last - framebufs->cur->buf.pos);
3420|
3421|      aob->state = NGHTTP2_OB_SEND_DATA;
3422|
3423|      break;
