151|static int session_call_error_callback(nghttp2_session *session,
152|                                       int lib_error_code, const char *fmt,
153|                                       ...) {
154|  size_t bufsize;
155|  va_list ap;
156|  char *buf;
157|  int rv;
158|  nghttp2_mem *mem;
159|
160|  if (!session->callbacks.error_callback &&
161|      !session->callbacks.error_callback2) {
162|    return 0;
163|  }
164|
165|  mem = &session->mem;
166|
167|  va_start(ap, fmt);
168|  rv = vsnprintf(NULL, 0, fmt, ap);
169|  va_end(ap);
170|
171|  if (rv < 0) {
172|    return NGHTTP2_ERR_NOMEM;
173|  }
174|
175|  bufsize = (size_t)(rv + 1);
176|
177|  buf = nghttp2_mem_malloc(mem, bufsize);
178|  if (buf == NULL) {
179|    return NGHTTP2_ERR_NOMEM;
180|  }
181|
182|  va_start(ap, fmt);
183|  rv = vsnprintf(buf, bufsize, fmt, ap);
184|  va_end(ap);
185|
186|  if (rv < 0) {
187|    nghttp2_mem_free(mem, buf);
188|    /* vsnprintf may return error because of various things we can
189|       imagine, but typically we don't want to drop session just for
190|       debug callback. */
191|    DEBUGF("error_callback: vsnprintf failed. The template was %s\n", fmt);
192|    return 0;
193|  }
194|
195|  if (session->callbacks.error_callback2) {
196|    rv = session->callbacks.error_callback2(session, lib_error_code, buf,
197|                                            (size_t)rv, session->user_data);
198|  } else {
199|    rv = session->callbacks.error_callback(session, buf, (size_t)rv,
200|                                           session->user_data);
201|  }
202|
203|  nghttp2_mem_free(mem, buf);
204|
205|  if (rv != 0) {
206|    return NGHTTP2_ERR_CALLBACK_FAILURE;
207|  }
208|
209|  return 0;
210|}
