212|static int session_terminate_session(nghttp2_session *session,
213|                                     int32_t last_stream_id,
214|                                     uint32_t error_code, const char *reason) {
215|  int rv;
216|  const uint8_t *debug_data;
217|  size_t debug_datalen;
218|
219|  if (session->goaway_flags & NGHTTP2_GOAWAY_TERM_ON_SEND) {
220|    return 0;
221|  }
222|
223|  /* Ignore all incoming frames because we are going to tear down the
224|     session. */
225|  session->iframe.state = NGHTTP2_IB_IGN_ALL;
226|
227|  if (reason == NULL) {
228|    debug_data = NULL;
229|    debug_datalen = 0;
230|  } else {
231|    debug_data = (const uint8_t *)reason;
232|    debug_datalen = strlen(reason);
233|  }
234|
235|  rv = nghttp2_session_add_goaway(session, last_stream_id, error_code,
236|                                  debug_data, debug_datalen,
237|                                  NGHTTP2_GOAWAY_AUX_TERM_ON_SEND);
238|
239|  if (rv != 0) {
240|    return rv;
241|  }
242|
243|  session->goaway_flags |= NGHTTP2_GOAWAY_TERM_ON_SEND;
244|
245|  return 0;
