299|static void session_inbound_frame_reset(nghttp2_session *session) {
300|  nghttp2_inbound_frame *iframe = &session->iframe;
301|  nghttp2_mem *mem = &session->mem;
302|  /* A bit risky code, since if this function is called from
303|     nghttp2_session_new(), we rely on the fact that
304|     iframe->frame.hd.type is 0, so that no free is performed. */
305|  switch (iframe->frame.hd.type) {
306|  case NGHTTP2_DATA:
307|    break;
308|  case NGHTTP2_HEADERS:
309|    nghttp2_frame_headers_free(&iframe->frame.headers, mem);
310|    break;
311|  case NGHTTP2_PRIORITY:
312|    nghttp2_frame_priority_free(&iframe->frame.priority);
313|    break;
314|  case NGHTTP2_RST_STREAM:
315|    nghttp2_frame_rst_stream_free(&iframe->frame.rst_stream);
316|    break;
317|  case NGHTTP2_SETTINGS:
318|    nghttp2_frame_settings_free(&iframe->frame.settings, mem);
319|
320|    nghttp2_mem_free(mem, iframe->iv);
321|
322|    iframe->iv = NULL;
323|    iframe->niv = 0;
324|    iframe->max_niv = 0;
325|
326|    break;
327|  case NGHTTP2_PUSH_PROMISE:
328|    nghttp2_frame_push_promise_free(&iframe->frame.push_promise, mem);
329|    break;
330|  case NGHTTP2_PING:
331|    nghttp2_frame_ping_free(&iframe->frame.ping);
332|    break;
333|  case NGHTTP2_GOAWAY:
334|    nghttp2_frame_goaway_free(&iframe->frame.goaway, mem);
335|    break;
336|  case NGHTTP2_WINDOW_UPDATE:
337|    nghttp2_frame_window_update_free(&iframe->frame.window_update);
338|    break;
339|  default:
340|    /* extension frame */
341|    if (check_ext_type_set(session->user_recv_ext_types,
342|                           iframe->frame.hd.type)) {
343|      nghttp2_frame_extension_free(&iframe->frame.ext);
344|    } else {
345|      switch (iframe->frame.hd.type) {
346|      case NGHTTP2_ALTSVC:
347|        if ((session->builtin_recv_ext_types & NGHTTP2_TYPEMASK_ALTSVC) == 0) {
348|          break;
349|        }
350|        nghttp2_frame_altsvc_free(&iframe->frame.ext, mem);
351|        break;
352|      case NGHTTP2_ORIGIN:
353|        if ((session->builtin_recv_ext_types & NGHTTP2_TYPEMASK_ORIGIN) == 0) {
354|          break;
355|        }
356|        nghttp2_frame_origin_free(&iframe->frame.ext, mem);
357|        break;
358|      case NGHTTP2_PRIORITY_UPDATE:
359|        if ((session->builtin_recv_ext_types &
360|             NGHTTP2_TYPEMASK_PRIORITY_UPDATE) == 0) {
361|          break;
362|        }
363|        /* Do not call nghttp2_frame_priority_update_free, because all
364|           fields point to sbuf. */
365|        break;
366|      }
367|    }
368|
369|    break;
370|  }
371|
372|  memset(&iframe->frame, 0, sizeof(nghttp2_frame));
373|  memset(&iframe->ext_frame_payload, 0, sizeof(nghttp2_ext_frame_payload));
374|
375|  iframe->state = NGHTTP2_IB_READ_HEAD;
376|
377|  nghttp2_buf_wrap_init(&iframe->sbuf, iframe->raw_sbuf,
378|                        sizeof(iframe->raw_sbuf));
379|  iframe->sbuf.mark += NGHTTP2_FRAME_HDLEN;
380|
381|  nghttp2_buf_free(&iframe->lbuf, mem);
382|  nghttp2_buf_wrap_init(&iframe->lbuf, NULL, 0);
383|
384|  iframe->raw_lbuf = NULL;
385|
386|  iframe->payloadleft = 0;
387|  iframe->padlen = 0;
388|}
