805|int nghttp2_session_reprioritize_stream(
806|    nghttp2_session *session, nghttp2_stream *stream,
807|    const nghttp2_priority_spec *pri_spec_in) {
808|  int rv;
809|  nghttp2_stream *dep_stream = NULL;
810|  nghttp2_priority_spec pri_spec_default;
811|  const nghttp2_priority_spec *pri_spec = pri_spec_in;
812|
813|  assert(session->pending_no_rfc7540_priorities != 1);
814|  assert(pri_spec->stream_id != stream->stream_id);
815|
816|  if (!nghttp2_stream_in_dep_tree(stream)) {
817|    return 0;
818|  }
819|
820|  if (pri_spec->stream_id != 0) {
821|    dep_stream = nghttp2_session_get_stream_raw(session, pri_spec->stream_id);
822|
823|    if (!dep_stream &&
824|        session_detect_idle_stream(session, pri_spec->stream_id)) {
825|
826|      nghttp2_priority_spec_default_init(&pri_spec_default);
827|
828|      dep_stream = nghttp2_session_open_stream(
829|          session, pri_spec->stream_id, NGHTTP2_FLAG_NONE, &pri_spec_default,
830|          NGHTTP2_STREAM_IDLE, NULL);
831|
832|      if (dep_stream == NULL) {
833|        return NGHTTP2_ERR_NOMEM;
834|      }
835|    } else if (!dep_stream || !nghttp2_stream_in_dep_tree(dep_stream)) {
836|      nghttp2_priority_spec_default_init(&pri_spec_default);
837|      pri_spec = &pri_spec_default;
838|    }
839|  }
840|
841|  if (pri_spec->stream_id == 0) {
842|    dep_stream = &session->root;
843|  } else if (nghttp2_stream_dep_find_ancestor(dep_stream, stream)) {
844|    DEBUGF("stream: cycle detected, dep_stream(%p)=%d stream(%p)=%d\n",
845|           dep_stream, dep_stream->stream_id, stream, stream->stream_id);
846|
847|    nghttp2_stream_dep_remove_subtree(dep_stream);
848|    rv = nghttp2_stream_dep_add_subtree(stream->dep_prev, dep_stream);
849|    if (rv != 0) {
850|      return rv;
851|    }
852|  }
853|
854|  assert(dep_stream);
855|
856|  if (dep_stream == stream->dep_prev && !pri_spec->exclusive) {
857|    /* This is minor optimization when just weight is changed. */
858|    nghttp2_stream_change_weight(stream, pri_spec->weight);
859|
860|    return 0;
861|  }
862|
863|  nghttp2_stream_dep_remove_subtree(stream);
864|
865|  /* We have to update weight after removing stream from tree */
866|  stream->weight = pri_spec->weight;
867|
868|  if (pri_spec->exclusive) {
869|    rv = nghttp2_stream_dep_insert_subtree(dep_stream, stream);
870|  } else {
871|    rv = nghttp2_stream_dep_add_subtree(dep_stream, stream);
872|  }
873|
874|  if (rv != 0) {
875|    return rv;
876|  }
877|
878|  return 0;
879|}
