1192|int nghttp2_session_add_rst_stream(nghttp2_session *session, int32_t stream_id,
1193|                                   uint32_t error_code) {
1194|  int rv;
1195|  nghttp2_outbound_item *item;
1196|  nghttp2_frame *frame;
1197|  nghttp2_stream *stream;
1198|  nghttp2_mem *mem;
1199|
1200|  mem = &session->mem;
1201|  stream = nghttp2_session_get_stream(session, stream_id);
1202|  if (stream && stream->state == NGHTTP2_STREAM_CLOSING) {
1203|    return 0;
1204|  }
