1206|  /* Sending RST_STREAM to an idle stream is subject to protocol
1207|     violation.  Historically, nghttp2 allows this.  In order not to
1208|     disrupt the existing applications, we don't error out this case
1209|     and simply ignore it. */
1210|  if (nghttp2_session_is_my_stream_id(session, stream_id)) {
1211|    if ((uint32_t)stream_id >= session->next_stream_id) {
1212|      return 0;
1213|    }
1214|  } else if (session->last_recv_stream_id < stream_id) {
1215|    return 0;
1216|  }
1217|
1218|  /* Cancel pending request HEADERS in ob_syn if this RST_STREAM
1219|     refers to that stream. */
