1222|    nghttp2_headers_aux_data *aux_data;
1223|    nghttp2_frame *headers_frame;
1224|
1225|    headers_frame = &nghttp2_outbound_queue_top(&session->ob_syn)->frame;
1226|    assert(headers_frame->hd.type == NGHTTP2_HEADERS);
1227|
1228|    if (headers_frame->hd.stream_id <= stream_id) {
1229|
1230|      for (item = session->ob_syn.head; item; item = item->qnext) {
1231|        aux_data = &item->aux_data.headers;
1232|
1233|        if (item->frame.hd.stream_id < stream_id) {
1234|          continue;
1235|        }
1236|
1237|        /* stream_id in ob_syn queue must be strictly increasing.  If
1238|           we found larger ID, then we can break here. */
1239|        if (item->frame.hd.stream_id > stream_id || aux_data->canceled) {
1240|          break;
1241|        }
1242|
1243|        aux_data->error_code = error_code;
1244|        aux_data->canceled = 1;
1245|
1246|        return 0;
1247|      }
1248|    }
1249|  }
1250|
1251|  item = nghttp2_mem_malloc(mem, sizeof(nghttp2_outbound_item));
1252|  if (item == NULL) {
1253|    return NGHTTP2_ERR_NOMEM;
1254|  }
1255|
1256|  nghttp2_outbound_item_init(item);
1257|
1258|  frame = &item->frame;
1259|
1260|  nghttp2_frame_rst_stream_init(&frame->rst_stream, stream_id, error_code);
1261|  rv = nghttp2_session_add_item(session, item);
1262|  if (rv != 0) {
1263|    nghttp2_frame_rst_stream_free(&frame->rst_stream);
1264|    nghttp2_mem_free(mem, item);
1265|    return rv;
1266|  }
1267|  return 0;
