1437|int nghttp2_session_close_stream(nghttp2_session *session, int32_t stream_id,
1438|                                 uint32_t error_code) {
1439|  int rv;
1440|  nghttp2_stream *stream;
1441|  nghttp2_mem *mem;
1442|  int is_my_stream_id;
1443|
1444|  mem = &session->mem;
1445|  stream = nghttp2_session_get_stream(session, stream_id);
1446|
1447|  if (!stream) {
1448|    return NGHTTP2_ERR_INVALID_ARGUMENT;
1449|  }
1450|
1451|  DEBUGF("stream: stream(%p)=%d close\n", stream, stream->stream_id);
1452|
