1454|    nghttp2_outbound_item *item;
1455|
1456|    item = stream->item;
1457|
1458|    rv = session_detach_stream_item(session, stream);
1459|
1460|    if (rv != 0) {
1461|      return rv;
1462|    }
1463|
1464|    /* If item is queued, it will be deleted when it is popped
1465|       (nghttp2_session_prep_frame() will fail).  If session->aob.item
1466|       points to this item, let active_outbound_item_reset()
1467|       free the item. */
