1474|  /* We call on_stream_close_callback even if stream->state is
1475|     NGHTTP2_STREAM_INITIAL. This will happen while sending request
1476|     HEADERS, a local endpoint receives RST_STREAM for that stream. It
1477|     may be PROTOCOL_ERROR, but without notifying stream closure will
1478|     hang the stream in a local endpoint.
1479|  */
1480|
1481|  if (session->callbacks.on_stream_close_callback) {
1482|    if (session->callbacks.on_stream_close_callback(
1483|            session, stream_id, error_code, session->user_data) != 0) {
1484|
1485|      return NGHTTP2_ERR_CALLBACK_FAILURE;
1486|    }
1487|  }
1488|
1489|  is_my_stream_id = nghttp2_session_is_my_stream_id(session, stream_id);
1490|
1491|  /* pushed streams which is not opened yet is not counted toward max
1492|     concurrent limits */
1493|  if ((stream->flags & NGHTTP2_STREAM_FLAG_PUSH)) {
1494|    if (!is_my_stream_id) {
1495|      --session->num_incoming_reserved_streams;
1496|    }
1497|  } else {
1498|    if (is_my_stream_id) {
1499|      --session->num_outgoing_streams;
1500|    } else {
1501|      --session->num_incoming_streams;
1502|    }
1503|  }
1504|
1505|  /* Closes both directions just in case they are not closed yet */
1506|  stream->flags |= NGHTTP2_STREAM_FLAG_CLOSED;
1507|
1508|  if (session->pending_no_rfc7540_priorities == 1) {
1509|    return nghttp2_session_destroy_stream(session, stream);
1510|  }
1511|
1512|  if ((session->opt_flags & NGHTTP2_OPTMASK_NO_CLOSED_STREAMS) == 0 &&
