2753|static int find_stream_on_goaway_func(void *entry, void *ptr) {
2754|  nghttp2_close_stream_on_goaway_arg *arg;
2755|  nghttp2_stream *stream;
2756|
2757|  arg = (nghttp2_close_stream_on_goaway_arg *)ptr;
2758|  stream = (nghttp2_stream *)entry;
2759|
2760|  if (nghttp2_session_is_my_stream_id(arg->session, stream->stream_id)) {
2761|    if (arg->incoming) {
2762|      return 0;
2763|    }
2764|  } else if (!arg->incoming) {
2765|    return 0;
2766|  }
2767|
2768|  if (stream->state != NGHTTP2_STREAM_IDLE &&
2769|      (stream->flags & NGHTTP2_STREAM_FLAG_CLOSED) == 0 &&
2770|      stream->stream_id > arg->last_stream_id) {
2771|    /* We are collecting streams to close because we cannot call
2772|       nghttp2_session_close_stream() inside nghttp2_map_each().
2773|       Reuse closed_next member.. bad choice? */
2774|    assert(stream->closed_next == NULL);
2775|    assert(stream->closed_prev == NULL);
2776|
2777|    if (arg->head) {
2778|      stream->closed_next = arg->head;
2779|      arg->head = stream;
2780|    } else {
2781|      arg->head = stream;
2782|    }
2783|  }
2784|
2785|  return 0;
