2788|/* Closes non-idle and non-closed streams whose stream ID >
2789|   last_stream_id.  If incoming is nonzero, we are going to close
2790|   incoming streams.  Otherwise, close outgoing streams. */
2791|static int session_close_stream_on_goaway(nghttp2_session *session,
2792|                                          int32_t last_stream_id,
2793|                                          int incoming) {
