7322|int nghttp2_session_recv(nghttp2_session *session) {
7323|  uint8_t buf[NGHTTP2_INBOUND_BUFFER_LENGTH];
7324|  while (1) {
7325|    ssize_t readlen;
7326|    readlen = session_recv(session, buf, sizeof(buf));
7327|    if (readlen > 0) {
7328|      ssize_t proclen = nghttp2_session_mem_recv(session, buf, (size_t)readlen);
7329|      if (proclen < 0) {
7330|        return (int)proclen;
7331|      }
7332|      assert(proclen == readlen);
7333|    } else if (readlen == 0 || readlen == NGHTTP2_ERR_WOULDBLOCK) {
7334|      return 0;
7335|    } else if (readlen == NGHTTP2_ERR_EOF) {
7336|      return NGHTTP2_ERR_EOF;
7337|    } else if (readlen < 0) {
7338|      return NGHTTP2_ERR_CALLBACK_FAILURE;
7339|    }
7340|  }
