7536|int nghttp2_session_add_settings(nghttp2_session *session, uint8_t flags,
7537|                                 const nghttp2_settings_entry *iv, size_t niv) {
7538|  nghttp2_outbound_item *item;
7539|  nghttp2_frame *frame;
7540|  nghttp2_settings_entry *iv_copy;
7541|  size_t i;
7542|  int rv;
7543|  nghttp2_mem *mem;
7544|  nghttp2_inflight_settings *inflight_settings = NULL;
7545|  uint8_t no_rfc7540_pri = session->pending_no_rfc7540_priorities;
7546|
7547|  mem = &session->mem;
7548|
7549|  if (flags & NGHTTP2_FLAG_ACK) {
7550|    if (niv != 0) {
7551|      return NGHTTP2_ERR_INVALID_ARGUMENT;
7552|    }
7553|
7554|    if (session->obq_flood_counter_ >= session->max_outbound_ack) {
7555|      return NGHTTP2_ERR_FLOODED;
7556|    }
7557|  }
7558|
7559|  if (!nghttp2_iv_check(iv, niv)) {
7560|    return NGHTTP2_ERR_INVALID_ARGUMENT;
7561|  }
7562|
7563|  for (i = 0; i < niv; ++i) {
7564|    if (iv[i].settings_id != NGHTTP2_SETTINGS_NO_RFC7540_PRIORITIES) {
7565|      continue;
7566|    }
7567|
7568|    if (no_rfc7540_pri == UINT8_MAX) {
7569|      no_rfc7540_pri = (uint8_t)iv[i].value;
7570|      continue;
7571|    }
7572|
7573|    if (iv[i].value != (uint32_t)no_rfc7540_pri) {
7574|      return NGHTTP2_ERR_INVALID_ARGUMENT;
7575|    }
7576|  }
7577|
7578|  item = nghttp2_mem_malloc(mem, sizeof(nghttp2_outbound_item));
7579|  if (item == NULL) {
7580|    return NGHTTP2_ERR_NOMEM;
7581|  }
7582|
7583|  if (niv > 0) {
7584|    iv_copy = nghttp2_frame_iv_copy(iv, niv, mem);
7585|    if (iv_copy == NULL) {
7586|      nghttp2_mem_free(mem, item);
7587|      return NGHTTP2_ERR_NOMEM;
7588|    }
7589|  } else {
7590|    iv_copy = NULL;
7591|  }
7592|
7593|  if ((flags & NGHTTP2_FLAG_ACK) == 0) {
7594|    rv = inflight_settings_new(&inflight_settings, iv, niv, mem);
7595|    if (rv != 0) {
7596|      assert(nghttp2_is_fatal(rv));
7597|      nghttp2_mem_free(mem, iv_copy);
7598|      nghttp2_mem_free(mem, item);
7599|      return rv;
7600|    }
7601|  }
7602|
7603|  nghttp2_outbound_item_init(item);
7604|
7605|  frame = &item->frame;
7606|
7607|  nghttp2_frame_settings_init(&frame->settings, flags, iv_copy, niv);
7608|  rv = nghttp2_session_add_item(session, item);
7609|  if (rv != 0) {
7610|    /* The only expected error is fatal one */
7611|    assert(nghttp2_is_fatal(rv));
7612|
7613|    inflight_settings_del(inflight_settings, mem);
7614|
7615|    nghttp2_frame_settings_free(&frame->settings, mem);
7616|    nghttp2_mem_free(mem, item);
7617|
7618|    return rv;
7619|  }
7620|
7621|  if (flags & NGHTTP2_FLAG_ACK) {
7622|    ++session->obq_flood_counter_;
7623|  } else {
7624|    session_append_inflight_settings(session, inflight_settings);
7625|  }
7626|
7627|  /* Extract NGHTTP2_SETTINGS_MAX_CONCURRENT_STREAMS and ENABLE_PUSH
7628|     here.  We use it to refuse the incoming stream and PUSH_PROMISE
7629|     with RST_STREAM. */
7630|
7631|  for (i = niv; i > 0; --i) {
7632|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_MAX_CONCURRENT_STREAMS) {
7633|      session->pending_local_max_concurrent_stream = iv[i - 1].value;
7634|      break;
7635|    }
7636|  }
7637|
7638|  for (i = niv; i > 0; --i) {
7639|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_ENABLE_PUSH) {
7640|      session->pending_enable_push = (uint8_t)iv[i - 1].value;
7641|      break;
7642|    }
7643|  }
7644|
7645|  for (i = niv; i > 0; --i) {
7646|    if (iv[i - 1].settings_id == NGHTTP2_SETTINGS_ENABLE_CONNECT_PROTOCOL) {
7647|      session->pending_enable_connect_protocol = (uint8_t)iv[i - 1].value;
7648|      break;
7649|    }
7650|  }
7651|
7652|  if (no_rfc7540_pri == UINT8_MAX) {
7653|    session->pending_no_rfc7540_priorities = 0;
7654|  } else {
7655|    session->pending_no_rfc7540_priorities = no_rfc7540_pri;
7656|  }
7657|
7658|  return 0;
