7661|int nghttp2_session_pack_data(nghttp2_session *session, nghttp2_bufs *bufs,
7662|                              size_t datamax, nghttp2_frame *frame,
7663|                              nghttp2_data_aux_data *aux_data,
7664|                              nghttp2_stream *stream) {
7665|  int rv;
7666|  uint32_t data_flags;
7667|  ssize_t payloadlen;
7668|  ssize_t padded_payloadlen;
7669|  nghttp2_buf *buf;
7670|  size_t max_payloadlen;
7671|
7672|  assert(bufs->head == bufs->cur);
7673|
7674|  buf = &bufs->cur->buf;
7675|
7676|  if (session->callbacks.read_length_callback) {
7677|
7678|    payloadlen = session->callbacks.read_length_callback(
7679|        session, frame->hd.type, stream->stream_id, session->remote_window_size,
7680|        stream->remote_window_size, session->remote_settings.max_frame_size,
7681|        session->user_data);
7682|
7683|    DEBUGF("send: read_length_callback=%zd\n", payloadlen);
7684|
7685|    payloadlen = nghttp2_session_enforce_flow_control_limits(session, stream,
7686|                                                             payloadlen);
7687|
7688|    DEBUGF("send: read_length_callback after flow control=%zd\n", payloadlen);
7689|
7690|    if (payloadlen <= 0) {
7691|      return NGHTTP2_ERR_CALLBACK_FAILURE;
7692|    }
7693|
7694|    if ((size_t)payloadlen > nghttp2_buf_avail(buf)) {
7695|      /* Resize the current buffer(s).  The reason why we do +1 for
7696|         buffer size is for possible padding field. */
7697|      rv = nghttp2_bufs_realloc(&session->aob.framebufs,
7698|                                (size_t)(NGHTTP2_FRAME_HDLEN + 1 + payloadlen));
7699|
7700|      if (rv != 0) {
7701|        DEBUGF("send: realloc buffer failed rv=%d", rv);
7702|        /* If reallocation failed, old buffers are still in tact.  So
7703|           use safe limit. */
7704|        payloadlen = (ssize_t)datamax;
7705|
7706|        DEBUGF("send: use safe limit payloadlen=%zd", payloadlen);
7707|      } else {
7708|        assert(&session->aob.framebufs == bufs);
7709|
7710|        buf = &bufs->cur->buf;
7711|      }
7712|    }
7713|    datamax = (size_t)payloadlen;
7714|  }
7715|
7716|  /* Current max DATA length is less then buffer chunk size */
7717|  assert(nghttp2_buf_avail(buf) >= datamax);
7718|
7719|  data_flags = NGHTTP2_DATA_FLAG_NONE;
7720|  payloadlen = aux_data->data_prd.read_callback(
7721|      session, frame->hd.stream_id, buf->pos, datamax, &data_flags,
7722|      &aux_data->data_prd.source, session->user_data);
7723|
7724|  if (payloadlen == NGHTTP2_ERR_DEFERRED ||
7725|      payloadlen == NGHTTP2_ERR_TEMPORAL_CALLBACK_FAILURE ||
7726|      payloadlen == NGHTTP2_ERR_PAUSE) {
7727|    DEBUGF("send: DATA postponed due to %s\n",
7728|           nghttp2_strerror((int)payloadlen));
7729|
7730|    return (int)payloadlen;
7731|  }
7732|
7733|  if (payloadlen < 0 || datamax < (size_t)payloadlen) {
7734|    /* This is the error code when callback is failed. */
7735|    return NGHTTP2_ERR_CALLBACK_FAILURE;
7736|  }
7737|
7738|  buf->last = buf->pos + payloadlen;
7739|  buf->pos -= NGHTTP2_FRAME_HDLEN;
7740|
7741|  /* Clear flags, because this may contain previous flags of previous
7742|     DATA */
7743|  frame->hd.flags = NGHTTP2_FLAG_NONE;
7744|
7745|  if (data_flags & NGHTTP2_DATA_FLAG_EOF) {
7746|    aux_data->eof = 1;
7747|    /* If NGHTTP2_DATA_FLAG_NO_END_STREAM is set, don't set
7748|       NGHTTP2_FLAG_END_STREAM */
