7750|        (data_flags & NGHTTP2_DATA_FLAG_NO_END_STREAM) == 0) {
7751|      frame->hd.flags |= NGHTTP2_FLAG_END_STREAM;
7752|    }
7753|  }
7754|
7755|  if (data_flags & NGHTTP2_DATA_FLAG_NO_COPY) {
7756|    if (session->callbacks.send_data_callback == NULL) {
7757|      DEBUGF("NGHTTP2_DATA_FLAG_NO_COPY requires send_data_callback set\n");
7758|
7759|      return NGHTTP2_ERR_CALLBACK_FAILURE;
7760|    }
7761|    aux_data->no_copy = 1;
7762|  }
7763|
7764|  frame->hd.length = (size_t)payloadlen;
7765|  frame->data.padlen = 0;
7766|
7767|  max_payloadlen = nghttp2_min(datamax, frame->hd.length + NGHTTP2_MAX_PADLEN);
