7769|  padded_payloadlen =
7770|      session_call_select_padding(session, frame, max_payloadlen);
7771|
7772|  if (nghttp2_is_fatal((int)padded_payloadlen)) {
7773|    return (int)padded_payloadlen;
7774|  }
7775|
7776|  frame->data.padlen = (size_t)(padded_payloadlen - payloadlen);
