7787|
7788|  if (frame->hd.length == 0 && (data_flags & NGHTTP2_DATA_FLAG_EOF) &&
7789|      (data_flags & NGHTTP2_DATA_FLAG_NO_END_STREAM)) {
7790|    /* DATA payload length is 0, and DATA frame does not bear
7791|       END_STREAM.  In this case, there is no point to send 0 length
7792|       DATA frame. */
7793|    return NGHTTP2_ERR_CANCEL;
7794|  }
7795|
7796|  return 0;
