8001|static int nghttp2_session_upgrade_internal(nghttp2_session *session,
8002|                                            const uint8_t *settings_payload,
8003|                                            size_t settings_payloadlen,
8004|                                            void *stream_user_data) {
8005|  nghttp2_stream *stream;
8006|  nghttp2_frame frame;
8007|  nghttp2_settings_entry *iv;
8008|  size_t niv;
8009|  int rv;
8010|  nghttp2_priority_spec pri_spec;
8011|  nghttp2_mem *mem;
8012|
8013|  mem = &session->mem;
8014|
8015|  if ((!session->server && session->next_stream_id != 1) ||
8016|      (session->server && session->last_recv_stream_id >= 1)) {
8017|    return NGHTTP2_ERR_PROTO;
8018|  }
8019|  if (settings_payloadlen % NGHTTP2_FRAME_SETTINGS_ENTRY_LENGTH) {
8020|    return NGHTTP2_ERR_INVALID_ARGUMENT;
8021|  }
8022|  /* SETTINGS frame contains too many settings */
8023|  if (settings_payloadlen / NGHTTP2_FRAME_SETTINGS_ENTRY_LENGTH >
8024|      session->max_settings) {
8025|    return NGHTTP2_ERR_TOO_MANY_SETTINGS;
8026|  }
8027|  rv = nghttp2_frame_unpack_settings_payload2(&iv, &niv, settings_payload,
8028|                                              settings_payloadlen, mem);
8029|  if (rv != 0) {
8030|    return rv;
8031|  }
8032|
8033|  if (session->server) {
8034|    nghttp2_frame_hd_init(&frame.hd, settings_payloadlen, NGHTTP2_SETTINGS,
8035|                          NGHTTP2_FLAG_NONE, 0);
8036|    frame.settings.iv = iv;
8037|    frame.settings.niv = niv;
8038|    rv = nghttp2_session_on_settings_received(session, &frame, 1 /* No ACK */);
8039|  } else {
8040|    rv = nghttp2_submit_settings(session, NGHTTP2_FLAG_NONE, iv, niv);
8041|  }
8042|  nghttp2_mem_free(mem, iv);
8043|  if (rv != 0) {
8044|    return rv;
8045|  }
8046|
8047|  nghttp2_priority_spec_default_init(&pri_spec);
8048|
8049|  stream = nghttp2_session_open_stream(
8050|      session, 1, NGHTTP2_STREAM_FLAG_NONE, &pri_spec, NGHTTP2_STREAM_OPENING,
8051|      session->server ? NULL : stream_user_data);
8052|  if (stream == NULL) {
8053|    return NGHTTP2_ERR_NOMEM;
8054|  }
8055|
8056|  /* We don't call nghttp2_session_adjust_closed_stream(), since this
8057|     should be the first stream open. */
8058|
8059|  if (session->server) {
8060|    nghttp2_stream_shutdown(stream, NGHTTP2_SHUT_RD);
8061|    session->last_recv_stream_id = 1;
8062|    session->last_proc_stream_id = 1;
8063|  } else {
8064|    nghttp2_stream_shutdown(stream, NGHTTP2_SHUT_WR);
8065|    session->last_sent_stream_id = 1;
8066|    session->next_stream_id += 2;
8067|  }
8068|  return 0;
